<script lang="ts">
 import { onMount } from 'svelte';import { goto } from '$app/navigation';
 import { createCustomAdventure, validateMapFile, MAP_MAX_COUNT, MAP_MAX_BYTES, type CustomAdventure } from '$lib/engine/customAdventures';
 import { getCustomAdventure, saveCustomAdventure } from '$lib/db/customAdventures';
 import { listCharacters, getCharacter } from '$lib/db/characters';import { BESTIARY } from '$lib/rules/bestiary';import type { Character } from '$lib/type';
 let { id = '' }: {id?:string}=$props();let draft=$state<CustomAdventure>(createCustomAdventure());let loading=$state(true);let busy=$state(false),error=$state(''),notice=$state('');let characters=$state<Character[]>([]),characterId=$state(''),enemyQuery=$state(''),monsterId=$state('wolf');
 const monsters=$derived(BESTIARY.filter(m=>`${m.name} ${m.description}`.toLocaleLowerCase('ru').includes(enemyQuery.trim().toLocaleLowerCase('ru'))));
 const mainFields=[['title','Название'],['summary','Краткое описание'],['region','Местность'],['levels','Уровни героев'],['players','Количество игроков'],['duration','Длительность'],['label','Метка приключения'],['opening','Начало истории'],['secret','Что происходит на самом деле']] as const;
 const listFields=[['tags','Темы и теги'],['hooks','Как вовлечь героев'],['pacing','Ритм истории'],['clues','Нити расследования'],['endings','Развязки'],['rewards','Награды']] as const;
 const recordSections=[{key:'locations',title:'Места и ощущения',fields:[['name','Название'],['atmosphere','Атмосфера'],['use','Как использовать']]},{key:'npcs',title:'Действующие лица',fields:[['name','Имя'],['role','Роль'],['motive','Мотив'],['voice','Голос и реплики']]},{key:'handouts',title:'Тексты улик',fields:[['title','Название'],['text','Текст']]}] as const;
 function rows(key:'locations'|'npcs'|'handouts'){return draft.adventure[key] as unknown as Record<string,string>[];}
 function addRow(section:typeof recordSections[number]){rows(section.key).push(Object.fromEntries(section.fields.map(([key])=>[key,''])));}
 onMount(async()=>{try{if(id){const found=await getCustomAdventure(id);if(!found)throw new Error('Приключение не найдено.');draft=found;}characters=await listCharacters();characterId=characters[0]?.id??'';}catch(cause){error=(cause as Error).message;}finally{loading=false;}});
 async function save(open=true){if(busy)return;busy=true;error='';notice='';try{draft.adventure.slug=`custom-${draft.id}`;await saveCustomAdventure(draft);notice='Приключение сохранено.';if(open)await goto(`/adventures/custom/${draft.id}`);}catch(cause){error=(cause as Error).message;}finally{busy=false;}}
 async function upload(event:Event){const input=event.currentTarget as HTMLInputElement;const files=Array.from(input.files??[]);if(!files.length)return;busy=true;error='';try{if(draft.maps.length+files.length>MAP_MAX_COUNT)throw new Error('Можно загрузить до четырёх карт.');const prepared=[];for(const file of files){if(file.size>MAP_MAX_BYTES)throw new Error(`${file.name}: файл больше 5 МБ.`);const bytes=new Uint8Array(await file.arrayBuffer());validateMapFile(file,bytes);const src=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('Не удалось прочитать карту.'));reader.readAsDataURL(file);});await new Promise<void>((resolve,reject)=>{const image=new Image();image.onload=()=>resolve();image.onerror=()=>reject(new Error('Повреждённое изображение карты.'));image.src=src;});prepared.push({id:crypto.randomUUID(),name:file.name,src,bytes:file.size,caption:file.name});}const first=draft.maps.length===0;draft.maps.push(...prepared);if(first)setMainMap(prepared[0].id);}catch(cause){error=(cause as Error).message;}finally{input.value='';busy=false;}}
 function setMainMap(mapId:string){const map=draft.maps.find(m=>m.id===mapId);if(map)draft.adventure.map={...draft.adventure.map,src:map.src,alt:map.name,caption:map.caption};}
 function removeMap(mapId:string){const removed=draft.maps.find(m=>m.id===mapId);draft.maps=draft.maps.filter(m=>m.id!==mapId);if(removed?.src===draft.adventure.map.src){if(draft.maps.length)setMainMap(draft.maps[0].id);else draft.adventure.map={src:'/forest.svg',alt:'Карта приключения',caption:'',markers:[]};}}
 function addScene(){draft.adventure.scenes.push({id:`scene-${crypto.randomUUID()}`,title:'Новая сцена',readAloud:'',goals:[],checks:[],outcomes:[],dialogue:[]});}
 function removeScene(sceneId:string){draft.adventure.scenes=draft.adventure.scenes.filter(s=>s.id!==sceneId);draft.enemies=draft.enemies.map(e=>e.sceneId===sceneId?{...e,sceneId:''}:e);}
 function addEnemy(){const monster=BESTIARY.find(m=>m.id===monsterId);if(monster)draft.enemies.push({id:crypto.randomUUID(),monsterId:monster.id,level:monster.baseLevel,count:1,sceneId:'',notes:''});}
 function addCharacter(){error='';const character=characters.find(c=>c.id===characterId);if(!character)return;if(draft.readyCharacters.some(c=>c.id===character.id)){error='Этот герой уже добавлен.';return;}draft.readyCharacters.push(JSON.parse(JSON.stringify(character)));}
 async function refreshCharacter(id:string){try{const current=await getCharacter(id);if(!current)throw new Error('Исходный лист героя не найден.');draft.readyCharacters=draft.readyCharacters.map(c=>c.id===id?current:c);}catch(cause){error=(cause as Error).message;}}
 async function createCharacter(){await save(false);if(!error)await goto(`/new?adventure=${draft.id}`);}
</script>
<svelte:head><title>{id?'Редактировать':'Создать'} приключение — Парма</title></svelte:head>
<main class="editor"><a href="/adventures">← Приключения</a><h1>{id?'Редактировать приключение':'Создать своё приключение'}</h1><p>Та же структура, что у готовых историй. Сохранение на этом устройстве, отдельно для текущего аккаунта. Перед сменой устройства скачайте копию приключения.</p>
 {#if loading}<p>Загружаем…</p>{:else}
 <form onsubmit={event=>{event.preventDefault();void save();}}><fieldset disabled={busy}>
 <section><h2>Об истории</h2>{#each mainFields as [key,label]}<label>{label}{#if ['opening','secret','summary'].includes(key)}<textarea rows="3" bind:value={draft.adventure[key]}></textarea>{:else}<input bind:value={draft.adventure[key]} required={key==='title'} maxlength={key==='title'?160:500}/>{/if}</label>{/each}</section>
 <section><h2>Карты</h2><p>PNG, JPEG или WebP · до 5 МБ на файл · не более четырёх карт. Первая карта — основная.</p><label>Загрузить карты<input type="file" accept="image/png,image/jpeg,image/webp" multiple onchange={upload}/></label>
 {#each draft.maps as map (map.id)}<div class="card"><img class="map-preview" src={map.src} alt={map.name}/><p>{map.name} · {(map.bytes/1024/1024).toFixed(2)} МБ</p><label>Подпись<input bind:value={map.caption} oninput={()=>{if(draft.adventure.map.src===map.src)draft.adventure.map.caption=map.caption;}}/></label><button type="button" onclick={()=>setMainMap(map.id)}>{draft.adventure.map.src===map.src?'Основная карта':'Сделать основной'}</button><button type="button" onclick={()=>removeMap(map.id)}>Убрать карту</button></div>{/each}
 <h3>Метки на основной карте</h3>{#each draft.adventure.map.markers as marker,i}<div class="card"><label>Название метки<input bind:value={marker.label}/></label><label>Заметка<input bind:value={marker.note}/></label><div class="inline"><label>X, %<input type="number" min="0" max="100" bind:value={marker.x}/></label><label>Y, %<input type="number" min="0" max="100" bind:value={marker.y}/></label></div><label><input type="checkbox" bind:checked={marker.gmOnly}/> Только сказителю</label><button type="button" onclick={()=>draft.adventure.map.markers.splice(i,1)}>Убрать метку</button></div>{/each}<button type="button" onclick={()=>draft.adventure.map.markers.push({id:crypto.randomUUID(),label:'Новая метка',x:50,y:50,note:'',gmOnly:false})}>Добавить метку</button></section>
 {#each listFields as [key,label]}<section><h2>{label}</h2><p>Каждый пункт — с новой строки.</p><textarea aria-label={label} rows="4" value={draft.adventure[key].join('\n')} oninput={event=>draft.adventure[key]=event.currentTarget.value.split('\n')}></textarea></section>{/each}
 {#each recordSections as section}<section><h2>{section.title}</h2>{#each rows(section.key) as row,i}<div class="card">{#each section.fields as [key,label]}<label>{label}<textarea rows="2" bind:value={row[key]}></textarea></label>{/each}<button type="button" onclick={()=>rows(section.key).splice(i,1)}>Убрать запись</button></div>{/each}<button type="button" onclick={()=>addRow(section)}>Добавить запись: {section.title}</button></section>{/each}
 <section><h2>Сцены</h2>{#each draft.adventure.scenes as scene (scene.id)}<div class="card"><label>Название сцены<input bind:value={scene.title}/></label><label>Текст для игроков<textarea rows="3" bind:value={scene.readAloud}></textarea></label>{#each [['goals','Задачи'],['checks','Проверки и действия'],['dialogue','Реплики'],['outcomes','Если всё пошло иначе']] as [key,label]}<label>{label}<textarea rows="3" value={(scene[key as 'goals'|'checks'|'dialogue'|'outcomes']??[]).join('\n')} oninput={event=>scene[key as 'goals'|'checks'|'dialogue'|'outcomes']=event.currentTarget.value.split('\n')}></textarea></label>{/each}<button type="button" onclick={()=>removeScene(scene.id)}>Убрать сцену</button></div>{/each}<button type="button" onclick={addScene}>Добавить сцену</button></section>
 <section><h2>Возможная встреча</h2><label>Название встречи<input bind:value={draft.adventure.encounter.name}/></label><label>Советы сказителю<textarea bind:value={draft.adventure.encounter.advice}></textarea></label></section>
 <section><h2>Готовые персонажи</h2><p>Добавьте своего героя как образец или создайте нового. Его можно доработать в листе, затем обновить образец здесь.</p><label>Ваш персонаж<select bind:value={characterId}><option value="">Выберите героя</option>{#each characters as c}<option value={c.id}>{c.name || 'Безымянный'} · ур. {c.level}</option>{/each}</select></label><button type="button" disabled={!characterId} onclick={addCharacter}>Добавить готового персонажа</button><button type="button" onclick={createCharacter}>Создать героя для приключения</button>{#each draft.readyCharacters as c (c.id)}<div class="card"><strong>{c.name} · ур. {c.level}</strong><div class="inline"><a href={`/char/${c.id}`} target="_blank" rel="noreferrer">Доработать лист</a><button type="button" onclick={()=>refreshCharacter(c.id)}>Обновить из листа</button><button type="button" onclick={()=>draft.readyCharacters=draft.readyCharacters.filter(item=>item.id!==c.id)}>Убрать образец</button></div></div>{/each}</section>
 <section><h2>Враги из бестиария</h2><label>Поиск врагов<input type="search" bind:value={enemyQuery}/></label><label>Враг<select bind:value={monsterId}>{#each monsters as m}<option value={m.id}>{m.name} · ур. {m.baseLevel}</option>{/each}</select></label><button type="button" disabled={!monsters.some(m=>m.id===monsterId)} onclick={addEnemy}>Добавить группу врагов</button>{#each draft.enemies as enemy (enemy.id)}{@const monster=BESTIARY.find(m=>m.id===enemy.monsterId)!}<div class="card"><h3>{monster.name}</h3><div class="inline"><label>Количество<input type="number" min="1" max="30" bind:value={enemy.count}/></label><label>Уровень<input type="number" min={monster.baseLevel} max={Math.max(20,monster.baseLevel)} bind:value={enemy.level}/></label></div><label>Сцена<select bind:value={enemy.sceneId}><option value="">Любая сцена</option>{#each draft.adventure.scenes as scene}<option value={scene.id}>{scene.title}</option>{/each}</select></label><label>Заметки о встрече<textarea bind:value={enemy.notes}></textarea></label><a href={`/gm/bestiary?monster=${enemy.monsterId}`} target="_blank" rel="noreferrer">Карточка в бестиарии</a><button type="button" onclick={()=>draft.enemies=draft.enemies.filter(e=>e.id!==enemy.id)}>Убрать группу</button></div>{/each}</section>
 <div class="save-bar"><button type="submit">{busy?'Сохраняем…':'Сохранить и открыть приключение'}</button><button type="button" onclick={()=>save(false)}>Сохранить черновик</button></div>
 </fieldset></form>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
</main>
<style>.editor{max-width:900px;margin:auto;padding:28px 20px 70px}h1{font-size:2.2rem;margin:20px 0}h2{font-size:1.6rem;margin:0 0 14px}h3{font-size:1.2rem}section{padding:22px;border:1px solid #aab9ac;border-radius:12px;margin:18px 0;background:#fffef8}fieldset{border:0;padding:0;min-width:0}label{display:flex;flex-direction:column;gap:5px;margin:12px 0}input:not([type=checkbox]),textarea,select{border:1px solid #aab9ac;border-radius:7px;padding:10px;width:100%;box-sizing:border-box;background:#fffef8;color:#24392d}textarea{resize:vertical}.card{padding:16px;border:1px solid #d5daca;border-radius:8px;margin:12px 0}.inline{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.inline label{flex:1;min-width:130px}.map-preview{max-height:240px;max-width:100%;object-fit:contain}button{border:1px solid #476b54;border-radius:7px;padding:9px 12px;margin:4px;background:#e9eddf;color:#173d30;cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}a{text-decoration:underline}.save-bar{position:sticky;bottom:10px;padding:12px;background:#fffef8;box-shadow:0 3px 15px #0002;border:1px solid #aab9ac;border-radius:10px}.save-bar button:first-child{background:#173d30;color:#fff}[role=alert]{color:#923737}@media(max-width:600px){.editor{padding:20px 12px}section{padding:16px}}</style>
